package io.github.miklires.mclans.clan;
import io.github.miklires.mclans.MClansPlugin;import io.github.miklires.mclans.api.*;import io.github.miklires.mclans.storage.ClanRepository;import java.time.Instant;import java.util.*;import java.util.concurrent.*;import org.bukkit.Bukkit;import org.bukkit.entity.Player;
public final class ClanService {
 private final MClansPlugin plugin;private final ClanRepository repository;private volatile ClanNamingPolicy naming;private volatile ClanProgression progression;private final Map<UUID,ClanView> playerClans=new ConcurrentHashMap<>();
 public ClanService(MClansPlugin plugin,ClanRepository repository){this.plugin=plugin;this.repository=repository;reload();}
 public void reload(){naming=new ClanNamingPolicy(plugin.getConfig().getString("naming.name-regex","[A-Za-z0-9_]{3,16}"),plugin.getConfig().getString("naming.tag-regex","[A-Za-z0-9]{2,5}"),Set.copyOf(plugin.getConfig().getStringList("naming.reserved")));List<ClanProgression.Level> levels=new ArrayList<>();for(Map<?,?> row:plugin.getConfig().getMapList("progression.levels"))levels.add(new ClanProgression.Level(((Number)row.get("level")).intValue(),((Number)row.get("points")).longValue(),((Number)row.get("members")).intValue()));progression=new ClanProgression(levels);}
 public CompletableFuture<ClanView> create(Player owner,String name,String tag){ClanNamingPolicy.Result result=naming.validate(name,tag);if(result!=ClanNamingPolicy.Result.ALLOWED)return CompletableFuture.failedFuture(new IllegalArgumentException(result.name()));return repository.create(owner.getUniqueId(),owner.getName(),name,tag).thenApply(clan->{playerClans.put(owner.getUniqueId(),clan);return clan;});}
 public CompletableFuture<Boolean> invite(Player actor,Player target){return context(actor.getUniqueId()).thenCompose(ctx->{if(ctx==null||!ctx.member().role().canManage())return CompletableFuture.completedFuture(false);long expiry=Instant.now().plusSeconds(Math.max(10,plugin.getConfig().getLong("invites.expire-seconds",120))).toEpochMilli();return repository.invite(ctx.clan().id(),target.getUniqueId(),target.getName(),actor.getUniqueId(),expiry).thenApply(v->true);});}
 public CompletableFuture<Boolean> accept(Player player,String nameOrTag){return repository.findClan(nameOrTag).thenCompose(found->{if(found.isEmpty())return CompletableFuture.completedFuture(false);ClanView clan=found.get();int limit=progression.forPoints(clan.points()).memberLimit();return repository.acceptInvite(player.getUniqueId(),player.getName(),clan.id(),limit).thenApply(ok->{if(ok)refresh(player.getUniqueId());return ok;});});}
 public CompletableFuture<Boolean> leave(Player player){return repository.leave(player.getUniqueId()).thenApply(ok->{if(ok)playerClans.remove(player.getUniqueId());return ok;});}
 public CompletableFuture<Boolean> disband(Player owner){ClanView clan=playerClans.get(owner.getUniqueId());if(clan==null)return CompletableFuture.completedFuture(false);return repository.disband(clan.id(),owner.getUniqueId()).thenApply(ok->{if(ok)playerClans.entrySet().removeIf(e->e.getValue().id()==clan.id());return ok;});}
 public CompletableFuture<Boolean> kick(Player actor,Player target){return context(actor.getUniqueId()).thenCompose(ctx->{if(ctx==null||!ctx.member().role().canManage()||ctx.clan().id()!=clanId(target.getUniqueId()))return CompletableFuture.completedFuture(false);return repository.member(target.getUniqueId()).thenCompose(member->{if(member.isEmpty()||member.get().role()==ClanRole.OWNER||rank(ctx.member().role())>=rank(member.get().role()))return CompletableFuture.completedFuture(false);return repository.removeMember(ctx.clan().id(),target.getUniqueId()).thenApply(ok->{if(ok)playerClans.remove(target.getUniqueId());return ok;});});});}
 public CompletableFuture<Boolean> setRole(Player actor,Player target,ClanRole role){return context(actor.getUniqueId()).thenCompose(ctx->{if(ctx==null||ctx.member().role()!=ClanRole.OWNER||ctx.clan().id()!=clanId(target.getUniqueId()))return CompletableFuture.completedFuture(false);return repository.setRole(ctx.clan().id(),target.getUniqueId(),role);});}
 public CompletableFuture<Boolean> setFriendlyFire(Player owner,boolean enabled){ClanView clan=playerClans.get(owner.getUniqueId());if(clan==null)return CompletableFuture.completedFuture(false);return repository.setFriendlyFire(clan.id(),owner.getUniqueId(),enabled).thenApply(ok->{if(ok)refreshClan(clan.id());return ok;});}
 public void refresh(UUID player){repository.clanOf(player).thenAccept(found->{if(found.isPresent())playerClans.put(player,found.get());else playerClans.remove(player);});}
 public void refreshClan(long id){playerClans.keySet().forEach(player->{ClanView clan=playerClans.get(player);if(clan!=null&&clan.id()==id)refresh(player);});}
 public boolean sameClan(UUID a,UUID b){ClanView first=playerClans.get(a),second=playerClans.get(b);return first!=null&&second!=null&&first.id()==second.id();}
 public boolean blocksFriendlyFire(UUID a,UUID b){ClanView clan=playerClans.get(a);return sameClan(a,b)&&clan!=null&&!clan.friendlyFire();}
 public void awardKill(Player killer,Player victim){ClanView clan=playerClans.get(killer.getUniqueId());if(clan==null||sameClan(killer.getUniqueId(),victim.getUniqueId()))return;long value=Math.max(0,plugin.getConfig().getLong("pvp.points-per-kill",10));long cooldown=Math.max(0,plugin.getConfig().getLong("pvp.same-victim-cooldown-seconds",3600))*1000;int level=progression.forPoints(clan.points()+value).level();repository.awardKill(clan.id(),killer.getUniqueId(),victim.getUniqueId(),value,cooldown,level).thenAccept(ok->{if(ok){refreshClan(clan.id());plugin.scheduler().player(killer,()->killer.sendMessage(color("&aКлан получил "+value+" очков.")));}});}
 public void clanChat(Player sender,String message){ClanView clan=playerClans.get(sender.getUniqueId());if(clan==null){sender.sendMessage(color("&cВы не состоите в клане."));return;}String formatted=color("&8[&e"+clan.tag()+"&8] &f"+sender.getName()+": &7"+message);Bukkit.getOnlinePlayers().stream().filter(p->sameClan(sender.getUniqueId(),p.getUniqueId())).forEach(p->plugin.scheduler().player(p,()->p.sendMessage(formatted)));}
 public CompletableFuture<Context> context(UUID player){return repository.clanOf(player).thenCombine(repository.member(player),(clan,member)->clan.isPresent()&&member.isPresent()?new Context(clan.get(),member.get()):null);}
 public ClanRepository repository(){return repository;}public Optional<ClanView> cached(UUID player){return Optional.ofNullable(playerClans.get(player));}private long clanId(UUID player){ClanView clan=playerClans.get(player);return clan==null?-1:clan.id();}private static int rank(ClanRole role){return switch(role){case OWNER->0;case OFFICER->1;case MEMBER->2;};}public static String color(String s){return org.bukkit.ChatColor.translateAlternateColorCodes('&',s);}public record Context(ClanView clan,ClanMemberView member){}
}
